			text = [=[Gracias a Mangletooth, la {link:horde}Horda{/link} supo quién dirigía de verdad los asaltos {link:razormane-quilboar}Razormane{/link} contra {link:the-crossroads}El Cruce{/link}: tres jabaespines salidos del {link:razorfen-kraul}Horado Rajacieno{/link}.]=],
