Translate("esMX", "tonga-runetotem", {
	title = "Tonga Runetotem",
	subtitle = "Druida de El Cruce",
	found = "El Cruce",
	hint = [=[Hable con el druida tauren que estudia los oasis de Los Baldíos.]=],
	allegiance = "Círculo Cenarion · Tauren",
	aliases = { "Tonga" },
	sections = {
		{
			title = "Resumen",
			text = [=[Tonga Runetotem es un druida {link:tauren}tauren{/link} enviado desde {link:thunder-bluff}Cima del Trueno{/link} para averiguar qué poder extraño se está filtrando en {link:the-barrens}Los Baldíos{/link}. Llora por la tierra verde que Los Baldíos fueron una vez. En los nuevos oasis encontró fisuras en la tierra, y en sus aguas un poder capaz de hacer brotar vida de semillas muertas y de retorcer a las bestias que las beben. Para él, es como si la tierra soñara y no pudiera despertar.]=],
		},
		{
			title = "Importancia",
			text = [=[La búsqueda de Tonga fue el primer hilo que llevó a los druidas de {link:thunder-bluff}Cima del Trueno{/link} hasta las {link:wailing-caverns}Cuevas de los Lamentos{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Encontró las fisuras bajo {link:the-forgotten-pools}Las Charcas del Olvido{/link} y {link:the-stagnant-oasis}El Oasis Estancado{/link}.
• Envió a {link:hamuul-runetotem}Hamuul Runetotem{/link} los caparazones corrompidos de las tortugas mordedoras del oasis.
• Prepara un ungüento para las gacelas enfermas de las llanuras del norte.
• Comparte sus hallazgos con Mura, de su mismo clan, en el {link:silverpine-forest}Bosque de Argénteos{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La tierra que sueña",
			hint = [=[Estudie los oasis para Tonga y tráigale lo que revelen las bestias.]=],
			text = [=[Las semillas muertas brotaron en la fisura de {link:the-stagnant-oasis}El Oasis Estancado{/link}. Los caparazones de las tortugas mordedoras llevaban una corrupción que Tonga nunca había visto. Supo entonces que las aguas eran la causa, y que las {link:wailing-caverns}Cuevas de los Lamentos{/link} debían de ser su origen.]=],
		},
	},
	mentions = {
		{ text = "Los oasis de {link:the-barrens}Los Baldíos{/link}" },
		{ text = "{link:the-forgotten-pools}Las Charcas del Olvido{/link}" },
		{ text = "{link:the-stagnant-oasis}El Oasis Estancado{/link}" },
		{ text = "Seres alterados" },
		{ text = "Mura Runetotem" },
		{ text = "Curar a los enfermos" },
		{ text = "La fuente principal" },
	},
	bonds = {
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "lo envió a Los Baldíos" },
	},
})

