	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[Walton es un curtidor que vive solo en una loma sobre {link:the-dry-hills}Las Colinas Áridas{/link}. Intercambia pieles con el cazador {link:vrang-wildgore}Vrang Wildgore{/link}, que advierte a los visitantes que no se alarmen por su aspecto. Walton fue una vez marinero de la armada de {link:kul-tiras}Kul Tiras{/link}. Cuando {link:daelin-proudmoore}Daelin Proudmoore{/link} hizo la guerra a la {link:horde}Horda{/link}, Walton se opuso a los métodos del almirante, sobre todo a la matanza de civiles. Su historia tiene más, dice, y no la cuenta entera.]=],
		},
		{
			title = "Importancia",
			text = [=[Walton es la prueba de que no todos los kultirenses siguieron al almirante de buen grado. Los hombres que aún enarbolan el estandarte de {link:daelin-proudmoore}Daelin{/link} no lo han olvidado.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dejó el servicio del almirante por la matanza de civiles.
• Curte las pieles que le trae {link:vrang-wildgore}Vrang Wildgore{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Invitados indeseados",
			hint = [=[Permanezca junto al ermitaño cuando unos desconocidos suban a la loma.]=],
			text = [=[Una partida de hombres subió a la loma: un cazarrecompensas llamado Terry Longdrink y marines de {link:kul-tiras}Kul Tiras{/link}. Venían por Walton. Cuando terminó la lucha y él seguía vivo, dijo que siempre había sabido que algún día aquello lo alcanzaría.]=],
