			hint = [=[Averigüe por qué acampan soldados kultirenses junto a la caravana destrozada.]=],
			text = [=[Walton había visto a hombres con la librea de {link:kul-tiras}Kul Tiras{/link} registrando el valle de abajo. Las órdenes halladas en su campamento procedían del teniente {link:lieutenant-benedict}Benedict{/link}, del {link:tiragarde-keep}Fuerte de Tiragarde{/link}. Buscaban a un desertor. El pasado, dijo Walton, por fin lo había alcanzado.]=],
		},
	},
	mentions = {
		{ text = "El curtidor ermitaño" },
	},
	bonds = {
