Translate("esMX", "chol-aruk", {
	title = "Chol'aruk",
	subtitle = "El Devorador",
	found = "Una cueva en la meseta de la Colina Espinosa",
	hint = [=[Busque la guarida de la bestia a la que los Razormane llaman el Devorador.]=],
	allegiance = "Jabaespines Razormane",
	aliases = { "El Devorador" },
	sections = {
		{
			title = "Resumen",
			text = [=[Chol'aruk es un {link:quilboar}jabaespín{/link} monstruoso que tiene su guarida en una cueva de la {link:thorn-hill}Colina Espinosa{/link}. Los {link:razormane-quilboar}Razormane{/link} lo llaman el Devorador. Quienes lo han visto dicen que es cinco veces más grande que un jabaespín corriente, que su sed de sangre nunca se sacia y que podría tragarse entero a un {link:orcs}orco{/link}. La mayoría de la gente no cree esas historias. Gur'ak, de {link:the-crossroads}El Cruce{/link}, sí las cree, y también Bainham, un soldado de la {link:alliance}Alianza{/link} en {link:ratchet}Trinquete{/link}. Ambos se han enfrentado antes a una bestia como esa, y ambos perdieron compañeros ante ella.]=],
		},
		{
			title = "Importancia",
			text = [=[Chol'aruk es una señal oscura. Si semejantes abominaciones llegaran a caminar entre los jabaespines en mayor número, el daño que podrían hacer a la tierra sería terrible.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Tiene su guarida en las profundidades de la {link:thorn-hill}Colina Espinosa{/link}.]=],
		},
	},
	mentions = {
		{ text = "Chol'aruk el Devorador, para Gur'ak" },
		{ text = "Chol'aruk el Devorador, para Bainham" },
	},
})

Translate("esMX", "kolkar-centaurs", {
	title = "Centauros Kolkar",
	aliases = { "Kolkar", "centauros Kolkar", "tribu Kolkar" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Kolkar son una tribu de {link:centaurs}centauros{/link} que recorren {link:the-barrens}Los Baldíos{/link} y las tierras que los rodean. Sus jinetes acampan junto a los oasis, cazan a las bestias que acuden a beber y caen sobre los viajeros de los caminos. Asaltaron a los {link:tauren}tauren{/link} durante años antes de que llegaran los orcos, y desde entonces asaltan a la {link:horde}Horda{/link}.]=],
		},
		{
			title = "En estos días",
			text = [=[Durante mucho tiempo, los Kolkar de {link:the-barrens}Los Baldíos{/link} estuvieron dispersos y desorganizados. Ahora han surgido nuevos líderes entre ellos: {link:barak-kodobane}Barak Kodobane{/link} cerca de {link:the-forgotten-pools}Las Charcas del Olvido{/link}, {link:verog-the-dervish}Verog el Derviche{/link} en {link:the-stagnant-oasis}El Oasis Estancado{/link} y {link:hezrul-bloodmark}Hezrul Bloodmark{/link}, el más grande de ellos, en el {link:lushwater-oasis}Oasis Aguaverde{/link}. Bajo estos cabecillas, la tribu se ha convertido en una verdadera amenaza. {link:regthar-deathgate}Regthar Deathgate{/link} los caza desde sus búnkeres al oeste de {link:the-crossroads}El Cruce{/link}, y cuando sus líderes cayeron, una partida de guerra llegó desde la patria Kolkar en {link:desolace}Desolace{/link} para vengarse. En {link:durotar}Durotar{/link}, otra partida domina el desfiladero rocoso del {link:kolkar-crag}Risco Kolkar{/link}.]=],
		},
	},
})

Translate("esMX", "razormane-quilboar", {
	title = "Jabaespines Razormane",
	aliases = { "Razormane", "tribu Razormane", "jabaespines Razormane" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Razormane son una tribu de {link:quilboar}jabaespines{/link} del norte y del sur de {link:the-barrens}Los Baldíos{/link}. Levantan sus campamentos entre grandes enredaderas espinosas que brotan de la tierra, y veneran al espíritu jabalí Agamaggan, de cuya sangre se dice que nacieron las espinas. Antes de que llegaran los orcos recorrían la tierra que hoy es {link:durotar}Durotar{/link}, y nunca han aceptado su pérdida.]=],
		},
		{
			title = "En estos días",
			text = [=[Los Razormane están en guerra con la {link:horde}Horda{/link} y con sus primos de la tribu Bristleback. Dominan la {link:thorn-hill}Colina Espinosa{/link} al este de {link:the-crossroads}El Cruce{/link}, {link:bramblescar}Rajazarza{/link} en las llanuras centrales y la {link:blackthorn-ridge}Loma Espina Negra{/link} en el sur. Sus asaltos a las caravanas de {link:durotar}Durotar{/link} los dirigían tres miembros de su tribu salidos del {link:razorfen-kraul}Horado Rajacieno{/link}: {link:nak}Nak{/link}, Kuz y {link:lok-orcbane}Lok Orcbane{/link}. El herrero del {link:camp-taurajo}Campamento Taurajo{/link} ha descubierto que sus armas son cada vez más resistentes. En una cueva de la Colina Espinosa, los Razormane hablan de una bestia monstruosa de su propia sangre, el Devorador.]=],
		},
	},
})
